import './App.css';
import { Navigate, Route, Routes } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Chatbot from './components/Chatbot';
import AuthModal from './components/AuthModal';
import ProductModal from './components/ProductModal';
import CompareModal from './components/CompareModal';
import Home from './pages/Home';
import ProductsPage from './pages/ProductsPage';
import ProductDetailsPage from './pages/ProductDetailsPage';
import CategoriesPage from './pages/CategoriesPage';
import DealsPage from './pages/DealsPage';
import AiRecommendationsPage from './pages/AiRecommendationsPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';
import OrderTrackingPage from './pages/OrderTrackingPage';
import DashboardPage from './pages/DashboardPage';
import AdminPage from './pages/AdminPage';
import StaticPage from './pages/StaticPage';
import NotFound from './pages/NotFound';
import { useStore } from './context/StoreContext';

function App() {
  const {
    authOpen,
    selectedProduct,
    compareOpen,
    closeAuth,
    closeProduct,
    closeCompare,
    toast,
    darkMode,
  } = useStore();

  return (
    <div className={`app-shell ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <Navbar />
      <main className="page-main" aria-live="polite">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/products" element={<ProductsPage />} />
          <Route path="/product/:productId" element={<ProductDetailsPage />} />
          <Route path="/categories" element={<CategoriesPage />} />
          <Route path="/categories/:categoryName" element={<ProductsPage />} />
          <Route path="/deals" element={<DealsPage />} />
          <Route path="/ai-recommendations" element={<AiRecommendationsPage />} />
          <Route path="/cart" element={<CartPage />} />
          <Route path="/checkout" element={<CheckoutPage />} />
          <Route path="/payment" element={<CheckoutPage step="payment" />} />
          <Route path="/track-order" element={<OrderTrackingPage />} />
          <Route path="/dashboard" element={<DashboardPage />} />
          <Route path="/admin" element={<AdminPage />} />
          <Route path="/about" element={<StaticPage type="about" />} />
          <Route path="/contact" element={<StaticPage type="contact" />} />
          <Route path="/faq" element={<StaticPage type="faq" />} />
          <Route path="/reviews" element={<StaticPage type="reviews" />} />
          <Route path="/login" element={<Navigate to="/" replace />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </main>
      <Footer />
      <Chatbot />
      {authOpen && <AuthModal onClose={closeAuth} />}
      {selectedProduct && <ProductModal product={selectedProduct} onClose={closeProduct} />}
      {compareOpen && <CompareModal onClose={closeCompare} />}
      {toast && <div className={`toast toast-${toast.type || 'info'}`}>{toast.message}</div>}
    </div>
  );
}

export default App;
